    @%p6 bra STORE_FAST;
    mul.wide.u32 %rd16, %r15, 4;
    add.s64 %rd17, %rd5, %rd16;
    ld.global.f32 %f9, [%rd17];
    mul.lo.u32 %r27, %r15, %r1;
    add.u32 %r28, %r27, %r11;
    mul.wide.u32 %rd18, %r28, 4;
    add.s64 %rd19, %rd2, %rd18;
    ld.global.v4.f32 {%f5,%f6,%f7,%f8}, [%rd19];
