    @%p9 bra SLOW_STORE;
    mul.wide.u32 %rd22, %r33, 4;
    add.s64 %rd23, %rd5, %rd22;
    ld.global.f32 %f15, [%rd23];
    mul.lo.u32 %r34, %r33, %r1;
    add.u32 %r35, %r34, %r32;
    mul.wide.u32 %rd24, %r35, 4;
    add.s64 %rd25, %rd2, %rd24;
    ld.global.f32 %f16, [%rd25];
    fma.rn.f32 %f14, %f15, %f16, %f14;
    add.u32 %r33, %r33, 1;
    bra SLOW_KLOOP;
