    mul.lo.u32 %r36, %r10, %r1;
    add.u32 %r37, %r36, %r32;
    mul.wide.u32 %rd26, %r37, 4;
    add.s64 %rd27, %rd3, %rd26;
    st.global.f32 [%rd27], %f14;
